pub(crate) struct AuthorityParts {
    pub authority: String,
    pub host: String,
    pub port: i32,
}

pub(crate) struct PathParts {
    pub path: String,
    pub query: String,
    pub fragment: String,
}

pub(crate) fn split_path_query_fragment(input: &str) -> PathParts {
    let (before_fragment, fragment) = match input.find('#') {
        Some(index) => (&input[..index], &input[index + 1..]),
        None => (input, ""),
    };

    let (path, query) = match before_fragment.find('?') {
        Some(index) => (&before_fragment[..index], &before_fragment[index + 1..]),
        None => (before_fragment, ""),
    };

    PathParts {
        path: path.to_string(),
        query: query.to_string(),
        fragment: fragment.to_string(),
    }
}

pub(crate) fn split_authority_and_suffix(input: &str) -> (&str, &str) {
    match input.find(|ch| matches!(ch, '/' | '?' | '#')) {
        Some(index) => (&input[..index], &input[index..]),
        None => (input, ""),
    }
}

pub(crate) fn parse_authority(input: &str) -> AuthorityParts {
    let (prefix, host_port) = match input.find('@') {
        Some(index) if index > 0 => (&input[..index + 1], &input[index + 1..]),
        Some(index) => ("", &input[index + 1..]),
        None => ("", input),
    };

    match host_port.find(':') {
        Some(index) => {
            let host = &host_port[..index];
            let raw_port = &host_port[index + 1..];

            match parse_port_prefix(raw_port) {
                Some(port) if (0..=65535).contains(&port) => AuthorityParts {
                    authority: format!("{prefix}{host}:{port}"),
                    host: host.to_string(),
                    port,
                },
                _ => AuthorityParts {
                    authority: format!("{prefix}{host}"),
                    host: host.to_string(),
                    port: -1,
                },
            }
        }
        None => AuthorityParts {
            authority: format!("{prefix}{host_port}"),
            host: host_port.to_string(),
            port: -1,
        },
    }
}

fn parse_port_prefix(input: &str) -> Option<i32> {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let sign = match bytes.get(index) {
        Some(b'+') => {
            index += 1;
            1i64
        }
        Some(b'-') => {
            index += 1;
            -1i64
        }
        _ => 1i64,
    };

    let digit_start = index;
    let mut value = 0i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = value.checked_mul(10)?.checked_add((bytes[index] - b'0') as i64)?;
        index += 1;
    }

    if index == digit_start {
        return None;
    }

    let signed = value.checked_mul(sign)?;

    if signed < i32::MIN as i64 || signed > i32::MAX as i64 {
        return None;
    }

    Some(signed as i32)
}

