impl Url {
    pub fn new(input: String) -> Self {
        match input.find("://") {
            Some(index) => {
                let scheme = input[..index].to_ascii_lowercase();
                let remainder = &input[index + 3..];
                let (authority_text, suffix) = split_authority_and_suffix(remainder);
