                let path_parts = split_path_query_fragment(suffix);
                let valid = !authority_parts.host.is_empty() || !path_parts.path.is_empty();

                Self {
                    scheme,
                    authority: authority_parts.authority,
                    port: authority_parts.port,
                    path: path_parts.path,
                    query: path_parts.query,
                    fragment: path_parts.fragment,
                    valid,
                }
            }
            None => {
                let path_parts = split_path_query_fragment(&input);
                let valid = !path_parts.path.is_empty();

                Self {
                    scheme: String::new(),
                    authority: String::new(),
                    port: -1,
                    path: path_parts.path,
                    query: path_parts.query,
                    fragment: path_parts.fragment,
                    valid,
                }
            }
        }
    }

