pub struct AuthorityParts {
    pub rendered: String,
    pub host: String,
    pub port: i32,
}

pub fn parse_authority(candidate: &str) -> AuthorityParts {
    if candidate.is_empty() {
        return AuthorityParts {
            rendered: String::new(),
            host: String::new(),
            port: -1,
        };
    }

    let host_start = candidate.find('@').map_or(0, |index| index + 1);
    let colon_index = candidate[host_start..]
        .find(':')
        .map(|offset| host_start + offset);

    match colon_index {
        Some(index) => {
            let authority_base = &candidate[..index];
            let host = &candidate[host_start..index];
            let port_text = &candidate[index + 1..];

            if let Some(port) = parse_cpp_i32_prefix(port_text) {
                if (0..=65535).contains(&port) {
                    return AuthorityParts {
                        rendered: format!("{authority_base}:{port}"),
                        host: host.to_string(),
                        port,
                    };
                }
            }

            AuthorityParts {
                rendered: authority_base.to_string(),
                host: host.to_string(),
                port: -1,
            }
        }
        None => AuthorityParts {
            rendered: candidate.to_string(),
            host: candidate[host_start..].to_string(),
            port: -1,
        },
    }
}

fn parse_cpp_i32_prefix(text: &str) -> Option<i32> {
    let trimmed = text.trim_start_matches(char::is_whitespace);
    let mut chars = trimmed.char_indices();

    let mut sign = 1_i64;
    let mut digit_start = 0;

    if let Some((_, ch)) = chars.next() {
        match ch {
            '+' => {
                digit_start = ch.len_utf8();
            }
            '-' => {
                sign = -1;
                digit_start = ch.len_utf8();
            }
            '0'..='9' => {}
            _ => return None,
        }
    } else {
        return None;
    }

    let mut value = 0_i64;
    let mut digit_count = 0_usize;
    let limit = if sign < 0 {
        i32::MAX as i64 + 1
    } else {
        i32::MAX as i64
    };

    for ch in trimmed[digit_start..].chars() {
        if !ch.is_ascii_digit() {
            break;
        }

        digit_count += 1;
        value = value.checked_mul(10)?;
        value = value.checked_add((ch as u8 - b'0') as i64)?;

        if value > limit {
            return None;
        }
    }

    if digit_count == 0 {
        return None;
    }

    let signed = if sign < 0 { -value } else { value };
    i32::try_from(signed).ok()
}

