use super::authority::parse_authority;

pub struct Url {
    scheme: String,
    authority: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl Url {
    pub fn new(input: &str) -> Self {
        parse_url(input)
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

fn parse_url(input: &str) -> Url {
    let mut scheme = String::new();
    let mut authority = String::new();
    let mut host = String::new();
    let mut port = -1;

    let remainder = if let Some(index) = input.find("://") {
        scheme = input[..index].to_string();

        let after_scheme = &input[index + 3..];
        let authority_end = find_authority_end(after_scheme);
        let authority_parts = parse_authority(&after_scheme[..authority_end]);

        authority = authority_parts.rendered;
        host = authority_parts.host;
        port = authority_parts.port;

        &after_scheme[authority_end..]
    } else {
        input
    };

    let (path, query, fragment) = parse_tail(remainder);
    let valid = !host.is_empty() || !path.is_empty();

    Url {
        scheme,
        authority,
        port,
        path,
        query,
        fragment,
        valid,
    }
}

fn find_authority_end(text: &str) -> usize {
    text.find(|ch| matches!(ch, '/' | '?' | '#'))
        .unwrap_or(text.len())
}

fn parse_tail(text: &str) -> (String, String, String) {
    let path_end = text
        .find(|ch| matches!(ch, '?' | '#'))
        .unwrap_or(text.len());
    let path = text[..path_end].to_string();

    let mut query = String::new();
    let mut fragment = String::new();
    let mut index = path_end;

    if index < text.len() && text.as_bytes()[index] == b'?' {
        index += 1;
        let query_end = text[index..]
            .find('#')
            .map(|offset| index + offset)
            .unwrap_or(text.len());
        query = text[index..query_end].to_string();
        index = query_end;
    }

    if index < text.len() && text.as_bytes()[index] == b'#' {
        fragment = text[index + 1..].to_string();
    }

    (path, query, fragment)
}

